package access

import (
	"crypto/rand"
	"encoding/hex"
)

const (
	// SessionPrefix marks provider execution sessions generated by AI Hub.
	SessionPrefix = "aihub-ses-"
	sessionBytes  = 16
	sessionMaxLen = 128
)

// NewSessionID returns a random provider execution session identifier.
func NewSessionID() (string, error) {
	buffer := make([]byte, sessionBytes)
	if _, err := rand.Read(buffer); err != nil {
		return "", err
	}

	return SessionPrefix + hex.EncodeToString(buffer), nil
}

// ValidSessionID reports whether a client-supplied session identifier is safe
// to preserve. The grammar is intentionally narrower than HTTP token syntax.
func ValidSessionID(value string) bool {
	if len(value) == 0 || len(value) > sessionMaxLen {
		return false
	}

	for index := 0; index < len(value); index++ {
		char := value[index]
		valid := char >= 'a' && char <= 'z' ||
			char >= 'A' && char <= 'Z' ||
			char >= '0' && char <= '9' ||
			char == '.' || char == '_' || char == ':' || char == '-'
		if !valid {
			return false
		}
	}

	return true
}
